    text_outside = re.sub(r'\[.*?\]', ' ', example_str, flags=re.DOTALL)

    text_outside = text_outside.strip()
    if not text_outside:
        return {}

    vectorizer = TfidfVectorizer()
    try:
        # Treat the concatenated text as a single document
        tfidf_matrix = vectorizer.fit_transform([text_outside])
    except ValueError:
        # Happens if the text contains no valid words (e.g., only punctuation)
        return {}

    feature_names = vectorizer.get_feature_names_out()
